"CREATE OR REPLACE FUNCTION public.book_booking(p_booking jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id text := NULLIF(p_booking->>'id', '');
  v_room_id text := NULLIF(p_booking->>'room_id', '');
  v_venue_id text := NULLIF(p_booking->>'venue_id', '');
  v_check_in date := (p_booking->>'check_in')::date;
  v_check_out date := (p_booking->>'check_out')::date;
  v_row jsonb;
BEGIN
  IF v_check_in IS NULL OR v_check_out IS NULL OR v_check_in >= v_check_out THEN
    RAISE EXCEPTION 'Check-in must be earlier than check-out.';
  END IF;
  IF v_room_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.bookings b WHERE b.room_id = v_room_id AND daterange(b.check_in, b.check_out) && daterange(v_check_in, v_check_out)) THEN RAISE EXCEPTION 'ROOM_UNAVAILABLE'; END IF;
  IF v_venue_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.bookings b WHERE public.booking_venue_key(b.venue_id) = public.booking_venue_key(v_venue_id) AND daterange(b.check_in, b.check_out) && daterange(v_check_in, v_check_out)) THEN RAISE EXCEPTION 'VENUE_UNAVAILABLE'; END IF;
  IF v_id IS NULL OR v_id = '' THEN v_id := gen_random_uuid()::text; END IF;
  INSERT INTO public.bookings (id, room_id, venue_id, guest_name, guest_email, guest_phone, guest_gender, guest_nationality, guest_address, check_in, check_out, source, status, payment_status, payment_method, payment_reference, payment_plan, downpayment_paid, balance_due, security_deposit, breakfast_orders, equipment_rentals, event_addons, companions, venue_excess_hours, expires_at, partner_deal_id, company_name, vehicle_plate, invoice_number, invoice_type, breakfast_included, contract_rate_override, promo_applied, applied_discount, early_check_in_hours, late_check_out_hours, actual_check_in, actual_check_out, notes, prepared_by, payment_records, venue_day_blocks, breakfast_days, breakfast_records, reference_number, registered_on)
  VALUES (v_id, v_room_id, v_venue_id, p_booking->>'guest_name', p_booking->>'guest_email', p_booking->>'guest_phone', p_booking->>'guest_gender', p_booking->>'guest_nationality', p_booking->>'guest_address', v_check_in, v_check_out, COALESCE((p_booking->>'source')::public.booking_source, 'website'), COALESCE((p_booking->>'status')::public.booking_status, 'pending'), NULLIF(p_booking->>'payment_status', '')::public.payment_status, p_booking->>'payment_method', p_booking->>'payment_reference', p_booking->>'payment_plan', COALESCE((p_booking->>'downpayment_paid')::numeric, 0), COALESCE((p_booking->>'balance_due')::numeric, 0), COALESCE((p_booking->>'security_deposit')::numeric, 0), (p_booking->'breakfast_orders')::jsonb, (p_booking->'equipment_rentals')::jsonb, (p_booking->'event_addons')::jsonb, (p_booking->'companions')::jsonb, COALESCE((p_booking->>'venue_excess_hours')::integer, 0), (p_booking->>'expires_at')::timestamptz, NULLIF(p_booking->>'partner_deal_id', '')::uuid, p_booking->>'company_name', p_booking->>'vehicle_plate', p_booking->>'invoice_number', p_booking->>'invoice_type', COALESCE((p_booking->>'breakfast_included')::boolean, false), (p_booking->>'contract_rate_override')::numeric, (p_booking->>'promo_applied')::boolean, (p_booking->'applied_discount')::jsonb, COALESCE((p_booking->>'early_check_in_hours')::integer, NULL), COALESCE((p_booking->>'late_check_out_hours')::integer, NULL), (p_booking->>'actual_check_in')::timestamptz, (p_booking->>'actual_check_out')::timestamptz, p_booking->>'notes', p_booking->>'prepared_by', (p_booking->'payment_records')::jsonb, COALESCE((p_booking->>'venue_day_blocks')::integer, NULL), (p_booking->'breakfast_days')::jsonb, (p_booking->'breakfast_records')::jsonb, p_booking->>'reference_number', (p_booking->>'registered_on')::date)
  RETURNING to_jsonb(bookings.*) INTO v_row; RETURN v_row;
END; $function$
"
"CREATE OR REPLACE FUNCTION public.update_booking(p_booking jsonb)
 RETURNS jsonb
